     *    Timer input clock = 170 MHz.
     *    f_PWM = f_clk / ((PSC + 1) * (ARR + 1))
     *    With PSC = 0: ARR + 1 = 170,000,000 / 20,000 = 8500 => ARR = 8499.
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

