    TIM1->CCR1 = 2125;

    /* 5. Configure Channel 1 as output in PWM mode 1 with preload enabled:
     *    CC1S = 00 (Channel 1 configured as output)
     *    OC1M = 0110 (PWM mode 1: active while CNT < CCR1, inactive otherwise)
     *    OC1PE = 1 (Output compare 1 preload enable)
