     *    - Mode: Alternate function mode (MODER[1:0] = 10b)
     *    - Alternate Function: AF2 (TIM1_CH1) in AFR[0] (AFRL0 = 2)
     *    - Output type: Push-Pull (OTYPER = 0)
     *    - Output speed: Very High Speed (OSPEEDR = 11b)
     *    - Pull-up/pull-down: No pull (PUPDR = 00b)
     */
    GPIOC->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE0_Pos);

    GPIOC->AFR[0] &= ~GPIO_AFRL_AFSEL0_Msk;
    GPIOC->AFR[0] |= (2U << GPIO_AFRL_AFSEL0_Pos);

    GPIOC->OTYPER &= ~GPIO_OTYPER_OT0;
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED0_Pos);
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD0_Msk;

