     *    - PWM mode 1: OC1M[3:0] = 0110b (active when CNT < CCR1, inactive when CNT >= CCR1)
     *    - Enable Output Compare 1 preload: OC1PE = 1
     */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2 | TIM_CCMR1_OC1PE);

