     *    - Active high polarity: CC1P = 0
     *    - Channel 1 output enable: CC1E = 1
     */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 6. Advanced-control timer specific:
     *    Enable Main Output (MOE bit in BDTR). Without this, outputs remain high-impedance.
     */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 7. Enable Auto-Reload Preload (ARPE) and Counter (CEN) */
    TIM1->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    /* 8. Generate an update event to transfer preloaded values into shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* Loop forever */
    while (1) {
    }
}
