#include "stm32g4xx.h"

void usart3_init(void)
{
    /* 1. Enable peripheral clocks for GPIOB and USART3 */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* 2. Configure PB10 (TX) and PB11 (RX) to Alternate Function AF7 (USART3) */
    /* Set PB10 and PB11 mode to alternate function (10b) */
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);

    /* Assign AF7 to PB10 and PB11 in AFR[1] (AFRH) */
    GPIOB->AFR[1] &= ~(GPIO_AFRH_AFSEL10_Msk | GPIO_AFRH_AFSEL11_Msk);
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* High speed output for TX */
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED10_Pos) | (3U << GPIO_OSPEEDR_OSPEED11_Pos);
    GPIOB->OTYPER  &= ~(GPIO_OTYPER_OT10 | GPIO_OTYPER_OT11);

    /* Pull-up on RX line to ensure idle high state; no pull on TX */
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD10_Msk | GPIO_PUPDR_PUPD11_Msk);
    GPIOB->PUPDR |= (1U << GPIO_PUPDR_PUPD11_Pos);

    /* 3. Configure frame format: 8 data bits, no parity, 1 stop bit, oversampling by 16 */
    /* USART3_CR1: M1=0, M0=0 (8-bit data), PCE=0 (no parity), OVER8=0 (oversample by 16) */
    USART3->CR1 = 0U;
    /* USART3_CR2: STOP[1:0] = 00b (1 stop bit) */
    USART3->CR2 = 0U;
    /* USART3_CR3: default reset state (no flow control) */
    USART3->CR3 = 0U;

    /* 4. Set baud rate register (BRR) before enabling USART:
     * Clock source = PCLK1 = 170 MHz, OVER8 = 0
     * BRR = USARTDIV = 170,000,000 / 115,200 = 1475.694 -> 1476 (0x05C4)
     */
    USART3->BRR = 1476U;

    /* 5. Enable transmitter (TE), receiver (RE), and USART enable (UE) */
    USART3->CR1 |= (USART_CR1_TE | USART_CR1_RE);
    USART3->CR1 |= USART_CR1_UE;
}
